const CLIENT = "(() => {\n'use strict';\nconst PREFIX = '/staff/observatory/api/';\nconst state = { role:'reviewer', tab:'overview', members:[], refreshing:false, memberPage:0, memberTotal:0, memberPageSize:50, memberQuery:'', memberReq:0 };\nconst byId = id => document.getElementById(id);\nconst esc = v => String(v == null ? '' : v).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst number = v => Number(v || 0).toLocaleString('en-US');\nfunction localDate(s, withTime=false) {\n if (!s) return '-';\n const value = typeof s==='number'||/^\\d+$/.test(String(s)) ? Number(s)*1000 : s;\n const dt = new Date(value);\n if (!Number.isFinite(dt.getTime())) return '-';\n const opts = withTime ? {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'} : {month:'short',day:'numeric',year:'numeric'};\n return dt.toLocaleString('en-US',opts);\n}\nfunction notify(message) { const box=byId('alert');box.textContent=message||'';box.hidden=!message; }\nasync function read(path) {\n // Bounded, same-origin service reads: never leave the dashboard spinning forever.\n const controller=typeof AbortController==='function'?new AbortController():null;\n const timeout=controller?setTimeout(()=>controller.abort(),12000):null;\n try {\n  const result=await fetch(PREFIX+path,{method:'GET',headers:{accept:'application/json'},\n   credentials:'same-origin',cache:'no-store',redirect:'manual',signal:controller?.signal});\n  if(result.type==='opaqueredirect'||(result.status>=300&&result.status<400))\n   throw new Error('Staff authentication redirected. Return to My Space and open Founder Console again.');\n  if(!(result.headers.get('content-type')||'').toLowerCase().includes('application/json'))\n   throw new Error('The staff service returned a non-JSON response. Check the session status and try again.');\n  const data=await result.json().catch(()=>({error:'Invalid staff service response'}));\n  if(!result.ok) {\n   if(result.status===401)throw new Error('Staff session not verified. Sign in through My Space, then return to Founder Console.');\n   if(result.status===403)throw new Error('Staff permission was denied. This session is not authorized for staff operations.');\n   if(result.status===429)throw new Error('Staff requests are temporarily limited. Retry shortly.');\n   throw new Error(data.error||'The staff service is temporarily unavailable.');\n  }\n  if(!data||typeof data!=='object'||Array.isArray(data)||data.error)\n   throw new Error('The staff service returned an invalid JSON payload.');\n  return data;\n } catch(error) {\n  if(controller?.signal.aborted)\n   throw new Error('The staff service did not respond within 12 seconds. Refresh to retry or check your session status.');\n  throw error;\n } finally {if(timeout!==null)clearTimeout(timeout);}\n}\nfunction card(label,value,explanation) {\n return '<article class=\"metric\"><div class=\"metric-label\">'+esc(label)+'</div><div class=\"metric-value\">'+esc(number(value))+'</div><div class=\"metric-explain\">'+esc(explanation)+'</div></article>';\n}\nfunction signal(label,value) {return '<div class=\"signal-row\"><span>'+esc(label)+'</span><strong>'+esc(number(value))+'</strong></div>';}\nfunction renderOverview(data) {\n state.role=data.role==='owner'?'owner':'reviewer';\n byId('role').textContent=state.role==='owner'?'OWNER CLEARANCE':'MODERATOR';\n document.querySelectorAll('.owner-only').forEach(node=>node.hidden=state.role!=='owner');\n if (state.role!=='owner' && ['members','rewards'].includes(state.tab)) selectTab('overview');\n byId('lastSync').textContent='Synced '+localDate(data.checkedAt,true);\n const c=data.counts||{};\n const main=[\n  ['Registered members',c.members,'Saved platform accounts'],['Verified accounts',c.verified,'Confirmed email addresses'],\n  ['New registrations / 7d',c.new7d,'Actual member signups'],['Members with sessions',c.sessionMembers,'Known auth sessions, not visits'],\n  \n  ['Published projects',c.publishedProjects,'Approved alpha submissions'],['Open moderation items',c.pendingTotal,'Unresolved queue signals']\n ];\n byId('metrics').innerHTML=main.map(item=>card(...item)).join('');\n const count=k=>Math.max(0,Number(c[k])||0);\n const pending=count('pendingProjects')+count('pendingForum')+count('projectReports')+count('forumReports');\n byId('missionStatus').textContent=pending?number(pending)+' recorded items need review':'No unresolved review items recorded';\n const priorities=[\n  ['Pending creations',count('pendingProjects'),'Open project reviews','/staff/projects'],\n  ['Forum review',count('pendingForum'),'Open staff command','/staff/command'],\n  ['Unresolved reports',count('projectReports')+count('forumReports'),'Open staff command','/staff/command'],\n  ['New members / 7d',count('new7d'),state.role==='owner'?'Member directory':'Aggregate only',null]\n ];\n byId('priorityActions').innerHTML=priorities.map(([label,value,action,url])=>\n  '<article class=\"priority-item\"><span class=\"priority-label\">'+esc(label)+'</span><strong class=\"priority-value\">'+esc(number(value))+'</strong>'+\n  (url?'<a class=\"priority-action\" href=\"'+esc(url)+'\">'+esc(action)+' &#8599;</a>':\n  state.role==='owner'?'<button class=\"priority-action\" type=\"button\" data-priority-members>Open member directory &#8599;</button>':\n  '<span class=\"priority-quiet\">'+esc(action)+'</span>')+'</article>'\n ).join('');\n byId('priorityActions').querySelectorAll('[data-priority-members]').forEach(btn=>btn.addEventListener('click',()=>selectTab('members')));\n byId('syncState').dataset.state='ready';\n byId('syncState').innerHTML='<span class=\"pulse-dot\"></span> LIVE DATA VERIFIED';\n const snapshot=new Date(data.checkedAt);const today=Number.isFinite(snapshot.getTime())?Date.UTC(snapshot.getUTCFullYear(),snapshot.getUTCMonth(),snapshot.getUTCDate()):Date.now();\n const byDay=new Map((data.signups||[]).map(x=>[String(x.day||''),Math.max(0,Number(x.n)||0)]));\n const points=Array.from({length:8},(_,index)=>{const day=new Date(today-(7-index)*86400000).toISOString().slice(0,10);return {day,n:byDay.get(day)||0};});\n const max=Math.max(1,...points.map(x=>Number(x.n)||0));\n byId('signups').innerHTML=points.length ? points.map(x=>'<div class=\"chart-day\" title=\"'+esc(number(x.n))+' registrations\"><div class=\"chart-column\" data-height=\"'+Math.max(2,Math.round(Number(x.n||0)/max*100))+'\"></div><span class=\"chart-label\">'+esc(String(x.day||'').slice(5))+'</span></div>').join('') : '<div class=\"empty\">No new registrations in this period</div>';\n byId('signups').querySelectorAll('.chart-column').forEach(bar=>{ bar.style.height=bar.dataset.height+'%'; });\n const social=[['Forum threads',c.threads],['Forum replies',c.replies],['Member wall posts',c.wallPosts],['Project votes',c.projectVotes],['Project comments',c.projectComments],['Project saves',c.projectSaves],['Earned recognition',c.recognitions],['Published projects',c.publishedProjects]];\n byId('interactions').innerHTML=social.map(x=>'<div class=\"signal-card\"><span class=\"key\">'+esc(x[0])+'</span><span class=\"val\">'+esc(number(x[1]))+'</span></div>').join('');\n\n byId('modMetrics').innerHTML=[\n   ['Pending projects',c.pendingProjects,'Awaiting approval'],['Pending forum items',c.pendingForum,'Threads and replies'],\n   ['Project reports',c.projectReports,'Unresolved reports'],['Forum reports',c.forumReports,'Unresolved reports']\n ].map(x=>card(...x)).join('');\n}\nfunction selectTab(name) {\n if (!['overview','members','rewards','moderation'].includes(name)) return;\n if (state.role!=='owner' && ['members','rewards'].includes(name)) return;\n state.tab=name;\n document.querySelectorAll('.workspace').forEach(node=>node.classList.toggle('active',node.id===name));\n document.querySelectorAll('[data-tab]').forEach(node=>{\n  const active=node.dataset.tab===name;\n  node.classList.toggle('active',active);\n  if (node.classList.contains('navitem')) {if (active)node.setAttribute('aria-current','page');else node.removeAttribute('aria-current');}\n });\n byId('main').scrollTop=0;\n}\n// Exact cosmetic IDs are stable in the member-recognition database.\n// Descriptive meanings mirror ANEVUM V091's public Aura Codex, not staff ranks.\nconst AURA_CATALOG = Object.freeze([{\"id\":\"none\",\"name\":\"Unadorned\",\"discipline\":\"Open Signal\",\"motto\":\"Let the work speak.\",\"meaning\":\"A clear player identity without an ambient signature. There is no disadvantage to leaving an aura off.\",\"appearance\":\"No animated atmosphere\"},{\"id\":\"aurora\",\"name\":\"Aurora\",\"discipline\":\"Discovery\",\"motto\":\"Follow the first light.\",\"meaning\":\"Curiosity, exploration and the willingness to ask new questions about the unknown.\",\"appearance\":\"Cold electric radiance\"},{\"id\":\"eclipse\",\"name\":\"Eclipse\",\"discipline\":\"Inquiry\",\"motto\":\"Look beyond what is visible.\",\"meaning\":\"Careful observation, critical thinking and the patience to examine assumptions.\",\"appearance\":\"Violet shadow halo\"},{\"id\":\"ember\",\"name\":\"Ember\",\"discipline\":\"Creation\",\"motto\":\"Bring the spark into form.\",\"meaning\":\"Building, writing and making: the persistence required to turn an idea into something real.\",\"appearance\":\"Warm stellar edge light\"},{\"id\":\"nebula\",\"name\":\"Nebula\",\"discipline\":\"Imagination\",\"motto\":\"Give possibility a shape.\",\"meaning\":\"Stories, art and worldbuilding that open space for perspectives and worlds not yet realized.\",\"appearance\":\"Soft rose cosmic clouds\"},{\"id\":\"transcosmic\",\"name\":\"Transcosmic\",\"discipline\":\"Continuance\",\"motto\":\"Carry the work beyond boundaries.\",\"meaning\":\"Connecting ideas and people across disciplines so discovery and creation can continue.\",\"appearance\":\"Continuance coral and violet\"}]);\nconst auraInfo = id => AURA_CATALOG.find(a => a.id === id) || AURA_CATALOG[0];\nfunction auraGuide(id,changed=false) {\n const a=auraInfo(id);\n return '<span class=\"aura-orb\" aria-hidden=\"true\"></span>'+\n   '<span class=\"aura-copy\"><strong>'+esc(a.name)+' · '+esc(a.discipline)+'</strong>'+\n   '<span>'+esc(a.meaning)+'</span><em>'+esc(a.motto)+'</em></span>'+\n   '<small class=\"aura-state\">'+(changed?'UNSAVED PREVIEW':'SAVED APPEARANCE')+'</small>';\n}\nfunction updateAuraPreview(memberId,id) {\n if(state.role!=='owner'||!AURA_CATALOG.some(a=>a.id===id))return;\n const m=state.members.find(a=>a.id===memberId);if(!m)return;\n const changed=id!==(m.aura||'none');\n const preview=[...document.querySelectorAll('[data-aura-preview]')].find(el=>el.dataset.auraPreview===memberId);\n const save=[...document.querySelectorAll('button[data-action=\"aura\"]')].find(el=>el.dataset.member===memberId);\n if(preview){preview.dataset.aura=id;preview.dataset.dirty=changed?'true':'false';preview.innerHTML=auraGuide(id,changed);}\n if(save){save.disabled=!changed;save.textContent=changed?'Apply aura':'Saved';}\n}\n\nfunction renderMembers() {\n if (state.role!=='owner') return;\n const members=state.members;\n byId('memberRows').innerHTML=members.length ? members.map(m=>{\n  const role=m.role||'member';\n  const action=role==='owner'?'<span class=\"mini-gold\">Protected owner</span>':\n    role==='reviewer'?'<button class=\"tiny-action danger\" type=\"button\" data-action=\"revoke\" data-member=\"'+esc(m.id)+'\">Revoke moderator</button>':\n    '<button class=\"tiny-action\" type=\"button\" data-action=\"grant\" data-member=\"'+esc(m.id)+'\">Grant moderator</button>';\n  const current=auraInfo(m.aura);\n  const options=AURA_CATALOG.map(a=>'<option value=\"'+esc(a.id)+'\"'+(current.id===a.id?' selected':'')+'>'+esc(a.name)+' · '+esc(a.discipline)+'</option>').join('');\n  return '<tr><td><strong>'+esc(m.displayName||m.name||'Member')+'</strong><small>'+(m.handle?'@'+esc(m.handle)+' / ':'')+esc(m.email||'')+'</small></td>'+ \n  '<td>'+esc(localDate(m.createdAt))+'</td><td>'+esc(localDate(m.lastSessionUpdate,true))+'<small>'+esc(number(m.sessionCount))+' saved session records</small></td>'+'<td><small>'+esc(m.recognitions||'No recorded grants')+'</small><div class=\"action-cell\"><select class=\"aura-select\" data-aura-member=\"'+esc(m.id)+'\" aria-label=\"Choose cosmetic aura for '+esc(m.displayName||m.name||'member')+'\">'+options+'</select><button class=\"tiny-action\" type=\"button\" data-action=\"aura\" data-member=\"'+esc(m.id)+'\" disabled>Saved</button></div>'+ \n  '<div class=\"aura-preview\" data-aura-preview=\"'+esc(m.id)+'\" data-aura=\"'+esc(current.id)+'\" data-dirty=\"false\" role=\"status\" aria-live=\"polite\">'+auraGuide(current.id)+'</div>'+\n  '<small class=\"aura-guard\">Cosmetic only: never grants clearance, XP, REP or awards.</small></td>'+ \n  '<td><span class=\"tag\">'+esc(role)+'</span>'+action+'</td></tr>';\n }).join('') : '<tr><td class=\"empty\" colspan=\"5\">No matching members</td></tr>';\n const begin=state.memberPage*state.memberPageSize;\n byId('memberPagerStatus').textContent=state.memberTotal>0 ?\n  'Showing '+number(begin+1)+'–'+number(begin+members.length)+' of '+number(state.memberTotal)+' matching members' : 'No matching members';\n byId('memberPrevious').disabled=state.memberPage<=0;\n byId('memberNext').disabled=begin+members.length>=state.memberTotal;\n}\nasync function loadMembers() {\n if(state.role!=='owner')return;\n const req=++state.memberReq;\n const path='members?page='+encodeURIComponent(state.memberPage)+'&q='+encodeURIComponent(state.memberQuery);\n const data=await read(path);\n if(req!==state.memberReq)return;\n state.members=data.members||[];\n state.memberPage=data.page||0;\n state.memberTotal=data.total||0;\n state.memberPageSize=data.pageSize||50;\n renderMembers();\n}\nfunction renderRewards(data) {\n const awards=data.awards||[];const auras=data.auras||[];\n byId('rewardList').innerHTML=awards.length?awards.map(x=>'<div class=\"signal-row\"><span>'+esc(x.kind)+' / <span class=\"mini-gold\">'+esc(x.id)+'</span></span><strong>'+esc(number(x.earned))+'</strong></div>').join(''):'<div class=\"empty\">No granted awards</div>';\n const totals=new Map(auras.map(a=>[a.aura,a.members]));\n byId('auraList').innerHTML=AURA_CATALOG.map(a=>'<div class=\"aura-distribution\" data-aura=\"'+esc(a.id)+'\">'+\n  '<span class=\"aura-orb\" aria-hidden=\"true\"></span><span><strong>'+esc(a.name)+'</strong><small>'+esc(a.discipline)+' · '+esc(a.appearance)+'</small></span>'+\n  '<strong class=\"aura-total\">'+esc(number(totals.get(a.id)||0))+'</strong></div>').join('');\n\n}\nfunction renderAudit(data) {\n const items=data.entries||[];\n byId('auditLog').innerHTML=items.length?items.map(x=>'<div class=\"signal-row\"><span>'+esc(x.action)+' <span class=\"mini-gold\">'+esc(x.target)+'</span><small>'+esc(localDate(x.createdAt,true))+'</small></span><span>'+esc(x.actor)+'</span></div>').join(''):'<div class=\"empty\">No staff role or aura changes recorded</div>';\n}\nasync function refresh() {\n if(state.refreshing)return;state.refreshing=true;notify('');\n const btn=byId('refresh');btn.disabled=true;btn.textContent='Syncing...';\n try {\n  const data=await read('overview');\n  if(!['owner','reviewer'].includes(data.role)||!data.counts||typeof data.counts!=='object'||Array.isArray(data.counts))\n   throw new Error('The staff overview response could not be verified.');\n  renderOverview(data);\n  if(state.role==='owner') {\n   const result=await Promise.allSettled([loadMembers(),read('rewards'),read('audit')]);\n   if(result[1].status==='fulfilled')renderRewards(result[1].value);\n   if(result[2].status==='fulfilled')renderAudit(result[2].value);\n   const failed=result.filter(r=>r.status==='rejected');\n   if(failed.length)notify('Some owner tools are unavailable. Check the management audit migration and current staff permissions.');\n  }\n }catch(e){\n   notify(e.message||'Could not load live Observatory data');\n   state.role='reviewer';state.members=[];state.memberReq++;\n   document.querySelectorAll('.owner-only').forEach(node=>node.hidden=true);\n   byId('role').textContent='UNVERIFIED';\n   for(const id of ['memberRows','memberPagerStatus','rewardList','auraList','auditLog','interactions'])byId(id).innerHTML='';\n   byId('syncState').dataset.state='error';\n   byId('syncState').innerHTML='<span class=\"pulse-dot\"></span> LIVE DATA UNAVAILABLE';\n   byId('lastSync').textContent='Connection unavailable';\n   byId('missionStatus').textContent='Live queue unavailable; no counts were loaded.';\n   byId('metrics').innerHTML='<div class=\"staff-connect-error\" role=\"status\">Live metrics could not be loaded. Use Refresh to retry or <a href=\"/__anevum_iren_staff_session_status_v001\">check staff session status</a>.</div>';\n   byId('priorityActions').innerHTML='<div class=\"staff-connect-error\">Review queue data unavailable. No actions or counts are inferred.</div>';\n   byId('signups').innerHTML='';\n   byId('modMetrics').innerHTML='';\n  }\n finally{state.refreshing=false;btn.disabled=false;btn.innerHTML='Refresh <span aria-hidden=\"true\">&#8635;</span>';}\n}\nasync function sendAction(kind,id) {\n if(state.role!=='owner')return;\n const m=state.members.find(x=>x.id===id);if(!m)return;\n let payload,url,message;\n if(kind==='aura') {\n  const selector=[...document.querySelectorAll('select[data-aura-member]')].find(node=>node.dataset.auraMember===id);\n  if(!selector)return;\n  const aura=selector.value;\n  if(!AURA_CATALOG.some(a=>a.id===aura)){notify('Unknown aura setting. No changes made.');return;}\n  if(aura===(m.aura||'none')){notify('That aura is already assigned.');return;}\n  const def=auraInfo(aura);\n  message='Assign '+def.name+' ('+def.discipline+') to '+(m.displayName||m.name)+'? This changes only the cosmetic player-card aura. Staff access, XP, reputation and awards stay unchanged.';\n  url=PREFIX+'aura'; payload={memberId:id,aura,revision:m.auraRevision};\n } else {\n  message=(kind==='grant'?'Grant moderator access to ':'Revoke moderator access from ')+(m.displayName||m.name)+'?';\n  url='/api/v1/member/staff-ops'; payload={kind:kind==='grant'?'staff-grant':'staff-revoke',memberId:id};\n }\n if(!window.confirm(message))return;\n notify('');\n try {\n  const result=await fetch(url,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify(payload)});\n  const body=await result.json().catch(()=>({}));\n  if(!result.ok)throw new Error(body.error||'Change refused by server');\n  await refresh();\n  notify('Updated '+(m.displayName||m.name)+'.');\n }catch(e){notify(e.message||'Change not applied');}\n}\ndocument.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>selectTab(el.dataset.tab)));\nbyId('refresh').addEventListener('click',refresh);\nlet searchTimer;\nbyId('memberSearch').addEventListener('input',event=>{\n state.memberQuery=event.target.value.trim();state.memberPage=0;\n byId('memberPagerStatus').textContent='Searching members...';\n clearTimeout(searchTimer);\n searchTimer=setTimeout(()=>loadMembers().catch(e=>notify(e.message||'Member search unavailable')),250);\n});\nbyId('memberPrevious').addEventListener('click',()=>{\n if(state.memberPage<=0)return;state.memberPage--;\n loadMembers().catch(e=>notify(e.message||'Member page unavailable'));\n});\nbyId('memberNext').addEventListener('click',()=>{\n if((state.memberPage+1)*state.memberPageSize>=state.memberTotal)return;\n state.memberPage++;\n loadMembers().catch(e=>notify(e.message||'Member page unavailable'));\n});\ndocument.addEventListener('change',event=>{\n const select=event.target.closest('select[data-aura-member]');\n if(select)updateAuraPreview(select.dataset.auraMember,select.value);\n});\ndocument.addEventListener('click',event=>{\n const action=event.target.closest('button[data-action]');\n if(action)sendAction(action.dataset.action,action.dataset.member);\n});\nrefresh();\n})();";

const ORIGIN = 'https://anevum.com';
const BASE = '/staff/observatory';
const AURAS = new Set(['none', 'aurora', 'eclipse', 'ember', 'nebula', 'transcosmic']);
const HEADERS = Object.freeze({
  'cache-control': 'private, no-store',
  'x-content-type-options': 'nosniff',
  'x-frame-options': 'DENY',
  'x-robots-tag': 'noindex, nofollow, noarchive',
  'referrer-policy': 'no-referrer',
  'vary': 'Cookie',
});
const CSP = [
  "default-src 'none'", "script-src 'self'", "style-src 'self'",
  "connect-src 'self'", "img-src 'self' data:", "font-src 'self'",
  "base-uri 'none'", "frame-ancestors 'none'", "form-action 'none'",
  "object-src 'none'",
].join('; ');

function respond(body, status = 200, contentType = 'application/json; charset=utf-8', isPage = false) {
  const headers = { ...HEADERS, 'content-type': contentType };
  if (isPage) headers['content-security-policy'] = CSP;
  return new Response(body, { status, headers });
}
const json = (value, status = 200) => respond(JSON.stringify(value), status);
const error = (status, message) => json({ error: message }, status);

async function getStaff(request, env) {
  if (!env || !env.APEX_AUTH || !env.MEMBER_DB) return null;
  const cookie = request.headers.get('cookie');
  if (!cookie || cookie.length > 8192) return null;
  try {
    const identity = new Request(`${ORIGIN}/api/v1/member/auth/get-session`, {
      method: 'GET',
      headers: { cookie, accept: 'application/json' },
      redirect:"manual",
      cache: 'no-store',
    });
    const result = await env.APEX_AUTH.fetch(identity);
    if (!result.ok || !result.headers.get('content-type')?.includes('application/json')) return null;
    const { session, user } = await result.json();
    if (!session || !user || typeof user.id !== 'string' || user.id.length < 1 || user.id.length > 128 ||
        typeof session.id !== 'string' || session.id.length === 0 ||
        session.userId !== user.id || user.emailVerified !== true ||
        typeof session.expiresAt !== 'string' || !Number.isFinite(Date.parse(session.expiresAt)) ||
        Date.parse(session.expiresAt) <= Date.now()) return null;
    const grant = await env.MEMBER_DB.prepare(
      'SELECT g.role FROM staff_access_grants g JOIN "user" u ON u.id=g.member_id ' +
      'WHERE g.member_id=? AND g.revoked_at IS NULL AND u.emailVerified=1 LIMIT 1'
    ).bind(user.id).first();
    if (!grant || !['owner', 'reviewer'].includes(grant.role)) return null;
    return { id: user.id, role: grant.role };
  } catch {
    return null;
  }
}

async function overview(db, staff) {
  const [summary, registrations] = await Promise.all([
    db.prepare(`SELECT
      (SELECT COUNT(*) FROM "user") AS members,
      (SELECT COUNT(*) FROM "user" WHERE emailVerified=1) AS verified,
      (SELECT COUNT(*) FROM "user" WHERE julianday(createdAt)>=julianday('now','-7 days')) AS new7d,
      (SELECT COUNT(DISTINCT userId) FROM session) AS sessionMembers,

      (SELECT COUNT(*) FROM member_forum_threads) AS threads,
      (SELECT COUNT(*) FROM member_forum_replies) AS replies,
      (SELECT COUNT(*) FROM member_wall_posts) AS wallPosts,
      (SELECT COUNT(*) FROM anevum_alpha_project_votes) AS projectVotes,
      (SELECT COUNT(*) FROM anevum_alpha_project_comments) AS projectComments,
      (SELECT COUNT(*) FROM anevum_alpha_project_saves) AS projectSaves,
      (SELECT COUNT(*) FROM member_recognition_grants WHERE revoked_at IS NULL) AS recognitions,
      (SELECT COUNT(*) FROM anevum_alpha_projects WHERE status='published') AS publishedProjects,
      (SELECT COUNT(*) FROM anevum_alpha_projects WHERE status='pending_review') AS pendingProjects,
      (SELECT COUNT(*) FROM member_forum_threads WHERE status='pending_review')+
      (SELECT COUNT(*) FROM member_forum_replies WHERE status='pending_review') AS pendingForum,
      (SELECT COUNT(*) FROM anevum_alpha_project_reports WHERE status='pending') AS projectReports,
      (SELECT COUNT(*) FROM member_forum_reports WHERE resolved_at IS NULL) AS forumReports
    `).first(),
    db.prepare(`SELECT substr(createdAt,1,10) AS day, COUNT(*) AS n
      FROM "user" WHERE julianday(createdAt)>=julianday('now','-7 days')
      GROUP BY day ORDER BY day ASC LIMIT 8`).all(),
  ]);
  const counts = summary || {};
  counts.pendingTotal = (counts.pendingProjects || 0) + (counts.pendingForum || 0) +
    (counts.projectReports || 0) + (counts.forumReports || 0);
  return json({
    role: staff.role,
    counts,
    signups: registrations.results || [],
    checkedAt: new Date().toISOString(),
    visitors: { status: 'unavailable', reason: 'Browser visitor analytics not yet connected to IREN' },
  });
}

async function members(db, staff, url) {
  if (staff.role !== 'owner') return error(403, 'Owner clearance required');
  const allowed = new Set(['q', 'page']);
  const params = url.searchParams;
  if ([...params.keys()].some(k => !allowed.has(k) || params.getAll(k).length !== 1))
    return error(400, 'Unrecognized member search filters');
  const q = (params.get('q') || '').trim();
  const pageString = params.get('page') || '0';
  if (q.length > 64 || /[\x00-\x1f\x7f]/.test(q) ||
      !/^(0|[1-9][0-9]{0,3})$/.test(pageString) || Number(pageString) > 1000)
    return error(400, 'Invalid member search');
  const page = Number(pageString);
  const pageSize = 50;
  const from = `FROM "user" u LEFT JOIN member_creator_profiles p ON p.user_id=u.id`;
  const where = q ? `WHERE instr(lower(u.name),lower(?))>0 OR
    instr(lower(u.email),lower(?))>0 OR
    instr(lower(COALESCE(p.display_name,'')),lower(?))>0 OR
    instr(lower(COALESCE(p.handle,'')),lower(?))>0` : '';
  const filter = q ? [q,q,q,q] : [];
  const countQuery = db.prepare(`SELECT COUNT(*) AS total ${from} ${where}`);
  const totalResult = q ? await countQuery.bind(...filter).first() : await countQuery.first();
  const total = Number(totalResult?.total || 0);
  const resolvedPage = Math.min(page,Math.max(0,Math.ceil(total/pageSize)-1));
  const result = await db.prepare(`SELECT u.id,u.name,u.email,u.createdAt,u.emailVerified,
    COALESCE(p.display_name,'') AS displayName,COALESCE(p.handle,'') AS handle,
    COALESCE(g.role,'member') AS role,COALESCE(ap.aura,'none') AS aura,
    COALESCE(ap.revision,0) AS auraRevision,
    (SELECT MAX(s.updatedAt) FROM session s WHERE s.userId=u.id) AS lastSessionUpdate,
    (SELECT COUNT(*) FROM session s WHERE s.userId=u.id) AS sessionCount,

    COALESCE((SELECT GROUP_CONCAT(r.recognition_id,', ') FROM member_recognition_grants r
      WHERE r.user_id=u.id AND r.revoked_at IS NULL),'') AS recognitions
    FROM "user" u
    LEFT JOIN member_creator_profiles p ON p.user_id=u.id
    LEFT JOIN staff_access_grants g ON g.member_id=u.id AND g.revoked_at IS NULL
    LEFT JOIN member_recognition_preferences ap ON ap.user_id=u.id

    ${where} ORDER BY u.createdAt DESC, u.id DESC LIMIT ? OFFSET ?`)
    .bind(...filter,pageSize,resolvedPage*pageSize).all();
  return json({ members: result.results || [], total, page:resolvedPage, pageSize,
    hasNext: (page+1)*pageSize < total });
}

async function rewards(db, staff) {
  if (staff.role !== 'owner') return error(403, 'Owner clearance required');
  const [awards, auras] = await Promise.all([
    db.prepare(`SELECT kind, recognition_id AS id, COUNT(*) AS earned
      FROM member_recognition_grants WHERE revoked_at IS NULL
      GROUP BY kind,recognition_id ORDER BY earned DESC,kind,id LIMIT 60`).all(),
    db.prepare(`SELECT aura,COUNT(*) AS members FROM member_recognition_preferences
      GROUP BY aura ORDER BY members DESC,aura`).all(),
  ]);
  return json({ awards: awards.results || [], auras: auras.results || [] });
}

async function audits(db, staff) {
  if (staff.role !== 'owner') return error(403, 'Owner clearance required');
  const result = await db.prepare(`SELECT x.action,x.actor,x.target,x.createdAt FROM (
    SELECT a.action,COALESCE(actor.name,'STAFF') AS actor,
      COALESCE(target.name,'MEMBER') AS target,a.created_at AS createdAt
      FROM staff_access_audit a LEFT JOIN "user" actor ON actor.id=a.actor_id
      LEFT JOIN "user" target ON target.id=a.member_id
    UNION ALL
    SELECT b.action,COALESCE(actor.name,'STAFF'),
      COALESCE(target.name,'MEMBER'),b.created_at
      FROM anevum_staff_management_audit b LEFT JOIN "user" actor ON actor.id=b.actor_id
      LEFT JOIN "user" target ON target.id=b.member_id
  ) x ORDER BY createdAt DESC LIMIT 60`).all();
  return json({ entries: result.results || [] });
}

async function readBoundedBody(request, maxBytes) {
  const reader = request.body?.getReader();
  if (!reader) return '';
  const chunks = [];
  let total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel();
        return null;
      }
      chunks.push(value);
    }
    const merged = new Uint8Array(total);
    let cursor = 0;
    for (const chunk of chunks) { merged.set(chunk,cursor); cursor += chunk.byteLength; }
    return new TextDecoder('utf-8',{fatal:true}).decode(merged);
  } catch { return null; }
  finally { reader.releaseLock(); }
}

async function changeAura(request, db, staff) {
  if (staff.role !== 'owner') return error(403, 'Owner clearance required');
  if (request.headers.get('origin') !== ORIGIN ||
      ![null, 'same-origin', 'none'].includes(request.headers.get('sec-fetch-site')))
    return error(403, 'Same-origin request required');
  if (!/^application\/json(?:\s*;|$)/i.test(request.headers.get('content-type') || ''))
    return error(415, 'JSON required');
  const declaredSize = Number(request.headers.get('content-length') || '0');
  if (!Number.isSafeInteger(declaredSize) || declaredSize < 0 || declaredSize > 1400)
    return error(413, 'Request too large');
  const raw = await readBoundedBody(request, 1200);
  if (raw === null) return error(413, 'Request too large');
  let data;
  try { data = JSON.parse(raw); } catch { return error(400, 'Invalid JSON'); }
  if (!data || typeof data !== 'object' || Array.isArray(data) ||
      Object.keys(data).sort().join(',') !== 'aura,memberId,revision' ||
      typeof data.memberId !== 'string' || !data.memberId || data.memberId.length > 128 ||
      !AURAS.has(data.aura) || !Number.isInteger(data.revision) ||
      data.revision < 0 || data.revision > 100000)
    return error(400, 'Invalid aura change');

  const recent = await db.prepare(`SELECT COUNT(*) AS n FROM anevum_staff_management_audit
    WHERE actor_id=? AND created_at>=unixepoch('now')-3600`).bind(staff.id).first();
  if (Number(recent?.n || 0) >= 20) return error(429, 'Hourly management limit reached');
  const previous = await db.prepare(`SELECT u.id,COALESCE(p.aura,'none') AS aura,
    COALESCE(p.revision,0) AS revision,
    CASE WHEN p.user_id IS NULL THEN 0 ELSE 1 END AS hasPreferences
    FROM "user" u LEFT JOIN member_recognition_preferences p ON p.user_id=u.id
    WHERE u.id=?`).bind(data.memberId).first();
  if (!previous) return error(404, 'Unknown member');
  if (Number(previous.revision) !== data.revision) return error(409, 'Member changed. Refresh first');
  if (previous.aura === data.aura) return json({ ok: true, unchanged: true });

  const now = Math.floor(Date.now() / 1000);
  const change = previous.hasPreferences
    ? db.prepare(`UPDATE member_recognition_preferences SET aura=?,revision=revision+1
       WHERE user_id=? AND revision=? AND aura<>?`)
       .bind(data.aura,data.memberId,data.revision,data.aura)
    : db.prepare(`INSERT INTO member_recognition_preferences(user_id,aura,revision)
       SELECT ?,?,1 WHERE EXISTS(SELECT 1 FROM "user" WHERE id=?)`)
       .bind(data.memberId,data.aura,data.memberId);
  const record = db.prepare(`INSERT INTO anevum_staff_management_audit
    (id,actor_id,member_id,action,old_value,new_value,created_at)
    SELECT ?,?,?,'aura-set',?,?,? WHERE changes()=1`)
    .bind(crypto.randomUUID(),staff.id,data.memberId,previous.aura,data.aura,now);
  const outcome = await db.batch([change,record]);
  if (outcome[0]?.meta?.changes !== 1 || outcome[1]?.meta?.changes !== 1)
    return error(409, 'Aura change not applied');
  return json({ ok: true, aura: data.aura });
}

export default {
  async fetch(request, env) {
    let url;
    try { url = new URL(request.url); } catch { return error(404, 'Not found'); }
    if (url.origin !== ORIGIN || url.protocol !== 'https:' || url.username || url.password ||
        ![BASE,`${BASE}/`,`${BASE}/app.js`,`${BASE}/styles.css`,
          `${BASE}/api/overview`,`${BASE}/api/members`,`${BASE}/api/rewards`,
          `${BASE}/api/audit`,`${BASE}/api/aura`].includes(url.pathname))
      return error(404, 'Not found');
    if (url.search && !(request.method === 'GET' && url.pathname === `${BASE}/api/members`))
      return error(400, 'Unexpected query');
    if (!['GET', 'POST'].includes(request.method)) return error(405, 'Method not allowed');
    const staff = await getStaff(request, env);
    if (!staff) return error(401, 'Valid staff session required');
    if (request.method === 'GET') {
      if (url.pathname === BASE || url.pathname === `${BASE}/`)
        return respond(PAGE, 200, 'text/html; charset=utf-8', true);
      if (url.pathname === `${BASE}/app.js`)
        return respond(CLIENT, 200, 'application/javascript; charset=utf-8');
      if (url.pathname === `${BASE}/styles.css`)
        return respond(STYLES, 200, 'text/css; charset=utf-8');
      try {
        switch(url.pathname) {
          case `${BASE}/api/overview`: return await overview(env.MEMBER_DB, staff);
          case `${BASE}/api/members`: return await members(env.MEMBER_DB, staff, url);
          case `${BASE}/api/rewards`: return await rewards(env.MEMBER_DB, staff);
          case `${BASE}/api/audit`: return await audits(env.MEMBER_DB, staff);
          default: return error(405, 'Method not allowed');
        }
      } catch { return error(503, 'Observatory data unavailable'); }
    }
    if (url.pathname !== `${BASE}/api/aura`) return error(405, 'Method not allowed');
    try { return await changeAura(request, env.MEMBER_DB, staff); }
    catch { return error(503, 'Management action unavailable'); }
  },
};
